JSONDATA;

    $questions = json_decode($rawJson, true);

    $updateStmt = $pdo->prepare("UPDATE questions SET 
        question = ?, 
        options = ?, 
        correct_option = ?, 
        cli_snippet = ?, 
        exhibit_image = ?, 
        original_source_image = ? 
        WHERE question_no = ?");

    $insertStmt = $pdo->prepare("INSERT INTO questions (
        question_no, question, options, correct_option, points, cli_snippet, exhibit_image, original_source_image
    ) VALUES (?, ?, ?, ?, 10, ?, ?, ?)");

    $checkStmt = $pdo->prepare("SELECT id FROM questions WHERE question_no = ? LIMIT 1");

    $updatedCount = 0;
    $insertedCount = 0;

    foreach ($questions as $q) {
        $qNo = $q['questionNo'];
        $statement = $q['question'];
        $optionsJson = json_encode($q['options'], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        $correctJson = json_encode($q['correctOption']);
        $cli = $q['cliSnippet'] ?? null;
        $exhibit = $q['exhibitImage'] ?? null;
        $orig = $q['originalSourceImage'] ?? null;

        $checkStmt->execute([$qNo]);
        $exists = $checkStmt->fetch();

        if ($exists) {
            $updateStmt->execute([$statement, $optionsJson, $correctJson, $cli, $exhibit, $orig, $qNo]);
            $updatedCount++;
        } else {
            $insertStmt->execute([$qNo, $statement, $optionsJson, $correctJson, $cli, $exhibit, $orig]);
            $insertedCount++;
        }
    }

    echo "SUCCESS: Seeded/Synchronized questions 101 to 207 into MySQL.\n";
    echo "Updated: $updatedCount, Inserted: $insertedCount, Total processed: " . count($questions) . "\n";

} catch (Exception $e) {
    echo "ERROR: " . $e->getMessage() . "\n";
}
